;; curriculum: Algebra-2 (gr 10) — logarithmic growth, domain; prerequisites: doubling, pole
;; math target: y = 1.6·ln(x+7) + 1 bursts upward then flattens forever; it does not exist for x ≤ −7.

app riya-level-log "1.1.0"
"riya level 9 · Log — the logarithm: a burst upward that flattens forever. Start at the domain wall x = −7, climb the burst, then phase-shift the curve to reach the far plateau. Catch 5 ★! Composed from std-platformer-body + std-objective-flow + std-fx-particles + std-pickup + std-tutorial-overlay, rendered through math-canvas so the function stays visible. Rebound into the riya-game-platformer organism (menu + all worlds)."

;; @exposure internal

orbital RiyaLogOrbital {
  uses Body from "std/behaviors/std-platformer-body"
  uses Gate from "std/behaviors/std-objective-flow"
  uses Particles from "std/behaviors/std-fx-particles"
  uses Pickup from "std/behaviors/std-pickup"
  uses Tutorial from "std/behaviors/std-tutorial-overlay"
  uses Genre from "std/behaviors/std-platformer-puzzle"

  type RiyaLogBody = {
    x : number!
    y : number!
    width : number!
    height : number!
    vx : number
    vy : number
    grounded : boolean
    facingRight : boolean
  }
  type RiyaLogPlatform = {
    id : string
    x : number!
    y : number!
    width : number!
    height : number!
    type : "ground" | "platform" | "hazard" | "goal"
  }
  type RiyaLogFx = {
    id : string!
    type : string!
    x : number!
    z : number
    y : number
    message : string
    ttl : number!
    maxTtl : number
    bornAt : number
    space : string
    effect : string
    color : string
    size : number
    vx : number
    vy : number
    vz : number
    particleCount : number
    animation : string
  }
  type RiyaLogCurveSample = {
    x : number!
    y : number!
  }
  type RiyaLogCurve = {
    label : string
    color : string
    samples : [RiyaLogCurveSample]!
    dash : "dashed" | "dotted"
  }
  type RiyaLogGuide = {
    kind : "vline" | "hline"!
    at : number!
    color : string
    dash : "dashed" | "dotted"
    label : string
  }
  type RiyaLogPickup = {
    id : string!
    x : number!
    y : number!
    kind : string!
    glyph : string
    message : string
    collected : boolean
  }
  type RiyaLogPhaseMod = {
    id : string!
    x0 : number!
    x1 : number!
    a : number!
    h : number!
    k : number!
  }
  type RiyaLogFxPreset = {
    type : string!
    color : string
    color2 : string
    size : number
    shape : string
    count : number
    glow : number
    vy : number
    animation : string
  }

  entity RiyaLogState [runtime, shared] {
    id : string!
    active : boolean = false
    body : RiyaLogBody = { x: -9, y: 1.2, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
    fell : boolean = false
    hazardId : string = ""
    goalId : string = ""
    skating : boolean = false
    pickups : [RiyaLogPickup] = []
    pickupCompleted : boolean = false
    total : number = 0
    score : number = 0
    objectivesLeft : number = 0
    result : string = "none"
    fx : [RiyaLogFx] = []
    celebrated : boolean = false
    seq : number = 0
    lastText : string = ""
    zoneId : string = "log"
    platforms : [RiyaLogPlatform] = []
    curves : [RiyaLogCurve] = []
    ghostCurves : [RiyaLogCurve] = []
    guides : [RiyaLogGuide] = []
  }

  entity LogTutorialData [runtime] {
    id : string!
    step : number = 0
    done : boolean = false
  }

  trait LogBody = Body.traits.PlatformerBody -> RiyaLogState {
    events {
      STEER: LOG_STEER
      JUMP: LOG_LEAP
      PLACE: LOG_PLACE
      RESTART: LOG_RESTART
      CURVE_MOD_ADD: LOG_CURVE_MOD_ADD
      SET_TUNING: LOG_SET_TUNING
      BODY_JUMPED: LOG_JUMPED
      BODY_LANDED: LOG_LANDED
      BODY_HAZARD: LOG_HAZARD
      BODY_GOAL: LOG_GOAL
      BODY_FELL: LOG_FELL
      BODY_SKATE_START: LOG_SKATE_ON
      BODY_SKATE_END: LOG_SKATE_OFF
      SET_PLATFORMS: LOG_SET_PLATFORMS
      SET_SKATE_CURVE: LOG_SET_SKATE_CURVE
    }
    config {
      running: true
      spawn: { x: -9, y: 1.2, width: 0.6, height: 0.6, vx: 0, vy: 0, grounded: false, facingRight: true }
      gravity: -24
      jumpStrength: 11
      moveSpeed: 5
      maxFallSpeed: 14
      xMin: -10
      xMax: 9.4
      killY: -3
      skate: true
      curveModsEnabled: true
      skateSnap: 0.9
    }
  }

  trait LogGate = Gate.traits.ObjectiveFlow -> RiyaLogState {
    events {
      PROGRESS: LOG_PROGRESS
      GAME_END: LOG_GAME_END
      RESTART: LOG_RESTART
    }
    config { running: true }
  }

  trait LogFx = Particles.traits.FxParticles -> RiyaLogState {
    events {
      BURST: LOG_BURST
    }
    config { running: true }
  }

  trait LogTutorialPreview -> LogTutorialData [interaction, instance] {
    initial: idle
    state idle {
      INIT -> idle
        (render-ui center null)
    }
  }

  trait LogTutorial = Tutorial.traits.TutorialOverlay -> LogTutorialData {
    events {
      SHOW: LOG_TUTORIAL_SHOW
      TUTORIAL_DONE: LOG_TUTORIAL_DONE
    }
    config {
      autoShow: true
      previewTrait: @trait.LogTutorialPreview
      steps: [
        { id: "intro", title: "Log", body: "A logarithm bursts upward then flattens forever. The domain wall x = −7 is forbidden. Skate the curve, collect ★, then grab the phase pad to shift the graph and reach the far plateau." }
      ]
    }
  }

  trait LogPickup = Pickup.traits.Pickup -> RiyaLogState {
    events {
      PICKED: LOG_PICKED
      COLLECT: LOG_COLLECT
      PICKUP_SET_COMPLETED: LOG_PICKUP_SET_COMPLETED
      SET_FEATURES: LOG_SET_FEATURES
    }
    config {
      running: true
      reachX: 0.7
      reachY: 1.2
    }
  }

  trait LogLevelData -> @rebindable RiyaLogState [lifecycle] {
    initial: active

    state active {
      INIT -> active
        (emit RIYA_LEVEL_DATA {
          id: "log"
          name: @config.worldName
          equation: @config.equation
          concept: @config.concept
          regionColor: @config.regionColor
          entryY: @config.entryY
          exitY: @config.exitY
          platforms: (array/map @config.platforms (fn p @p))
          stars: (array/map @config.stars (fn s @s))
          skateCurve: (array/map @config.skateCurve (fn c @c))
          curveOverlay: (array/map @config.curveOverlay (fn c @c))
          ghostCurves: (array/map @config.ghostCurves (fn c @c))
          guides: (array/map @config.guides (fn g @g))
          phaseMods: (array/map @config.phaseMods (fn m @m))
        })
    }

    emits {
      RIYA_LEVEL_DATA -> external {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaLogPlatform]!
        stars : [RiyaLogPickup]!
        skateCurve : [RiyaLogCurveSample]
        curveOverlay : [RiyaLogCurve]
        ghostCurves : [RiyaLogCurve]
        guides : [RiyaLogGuide]
        phaseMods : [RiyaLogPhaseMod]
      }
        @description "The zone's canonical static geometry + pedagogy, broadcast once on INIT in zone-local coordinates. This atom's own play trait consumes it to seed the body/pickup authorities and the render; the riya open-world organism consumes the same event and applies its zone offset, so standalone and composed can never diverge."
        @tier "domain"
    }

    config {
      worldName : string = "Log"
        @label "World Name"
        @description "This world's display name — the open world's zone banner reads it from RIYA_LEVEL_DATA."
        @tier "presentation"
      equation : string = "y = 1.6·ln(x+7) + 1"
        @label "Equation"
        @description "The zone's skate/banner equation."
        @tier "presentation"
      concept : string = "the logarithm bursts upward then flattens forever; the domain wall x = −7 is forbidden; a phase shift repositions the curve to unlock the far plateau"
        @label "Concept"
        @description "The world's one math idea."
        @tier "presentation"
      regionColor : string = "#38bdf8"
        @label "Region Color"
        @description "Zone band accent in the open world."
        @tier "presentation"
      entryY : number = 0
        @label "Entry Y"
        @description "Run-surface height at the zone's left edge; the open world stitches its incoming bridge to this."
        @tier "domain"
      exitY : number = 5.5
        @label "Exit Y"
        @description "Run-surface height at the zone's right edge; the open world stitches its outgoing bridge to this."
        @tier "domain"
      platforms : [RiyaLogPlatform] = [
        { id: "start", x: -9.6, y: -2, width: 3.2, height: 2, type: "ground" }
        { id: "b0", x: -6.4, y: -2, width: 1.6, height: 3.5, type: "ground" }
        { id: "b1", x: -4.8, y: -2, width: 1.6, height: 4.8, type: "ground" }
        { id: "b2", x: -3.2, y: -2, width: 1.6, height: 5.4, type: "ground" }
        { id: "b3", x: -1.6, y: -2, width: 1.6, height: 5.9, type: "ground" }
        { id: "b4", x: 0, y: -2, width: 1.6, height: 6.3, type: "ground" }
        { id: "b5", x: 1.6, y: -2, width: 1.6, height: 6.6, type: "ground" }
        { id: "b6", x: 3.2, y: -2, width: 1.6, height: 6.8, type: "ground" }
        { id: "b7", x: 4.8, y: -2, width: 1.6, height: 7.1, type: "ground" }
        { id: "b8", x: 6.4, y: -2, width: 1.6, height: 7.2, type: "ground" }
        { id: "plateau", x: 8, y: -2, width: 3.2, height: 7.5, type: "ground" }
      ]
