  trait RiyaLogGenre = Genre.traits.PlatformerPuzzle -> RiyaLogState {
    config {
      agencyTrait: @trait.LogBody
      challengeTrait: @trait.LogBody
      goalTrait: @trait.LogGate
      rewardTrait: @trait.LogPickup
      feedbackTrait: @trait.LogFx
    }
  }

  trait RiyaLogPlay -> @rebindable RiyaLogState [interaction, instance] {
    initial: idle

    state idle {
      INIT -> idle
        (set @entity.active true)
        (set @entity.celebrated false)
        (set @entity.score 0)
        (emit LOG_RESTART { id: "board" })
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "LOG_LEFT", KeyA: "LOG_LEFT", ArrowRight: "LOG_RIGHT", KeyD: "LOG_RIGHT", ArrowUp: "LOG_JUMP", KeyW: "LOG_JUMP", Space: "LOG_JUMP" }
            keyUpMap: { ArrowLeft: "LOG_STOP", KeyA: "LOG_STOP", ArrowRight: "LOG_STOP", KeyD: "LOG_STOP" }
            curves: (array/concat
              (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
              @entity.ghostCurves)
            guides: @entity.guides
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "phase") "#22d3ee" @config.starColor), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })
        (render-ui hud-bottom {
          type: stack
          direction: horizontal
          justify: start
          className: "p-4"
          children: [ { type: control-grid, kind: "dpad", visibility: "auto", directionEvents: { left: "LOG_LEFT", right: "LOG_RIGHT", up: "LOG_JUMP" }, directionReleaseEvents: { left: "LOG_STOP", right: "LOG_STOP" } } ]
        })

      RIYA_LEVEL_DATA -> idle when (== @payload.id "log")
        (set @entity.curves @payload.curveOverlay)
        (set @entity.ghostCurves @payload.ghostCurves)
        (set @entity.guides @payload.guides)
        (set @entity.objectivesLeft (array/len @payload.stars))
        (emit LOG_SET_PLATFORMS { platforms: @payload.platforms })
        (emit LOG_SET_SKATE_CURVE { curve: @payload.skateCurve })
        (emit LOG_SET_FEATURES { features: @payload.stars })

      LOG_LEFT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit LOG_STEER { dir: -1 })

      LOG_RIGHT -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit LOG_STEER { dir: 1 })

      LOG_STOP -> idle when (== @entity.active true)
        (emit LOG_STEER { dir: 0 })

      LOG_JUMP -> idle when (and (== @entity.active true) (== @entity.result "none"))
        (emit LOG_LEAP {})

      LOG_FELL -> idle when (== @entity.active true)
        (emit LOG_PLACE { x: @config.respawnX, y: @config.respawnY })
        (emit LOG_BURST { particles: (array/map [ "fx-log-fell" ] (fn fid { id: @fid, type: "info", x: @config.respawnX, z: @config.respawnY, message: "💫", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })

      LOG_SKATE_ON -> idle when (== @entity.active true)
        (emit LOG_BURST { particles: (array/concat
          { id: "narrative-skate", type: "narrative", x: @entity.body.x, z: (+ @entity.body.y 2), y: 0, message: "x ≤ −7 does not exist", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f87171", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" }
          {
            id: "fx-log-skate",
            type: "info",
            x: @payload.x,
            z: (+ @payload.y 0.6),
            y: 0,
            message: (str/concat @config.equationText " · x = " (math/round (+ @payload.x 0.3) 1)),
            ttl: 4,
            maxTtl: 4,
            bornAt: (time/now),
            space: "world",
            effect: "float-text",
            color: "#38bdf8",
            size: 0.6,
            vx: 0,
            vy: 0,
            vz: 0,
            particleCount: 1,
            animation: ""
          }
        ) })
      LOG_PICKED -> idle when (== @entity.active true)
        (emit LOG_BURST { particles: (array/map [ "fx-pickup" ] (fn fid { id: (str/concat @fid "-" @payload.id), type: "pickup", x: @payload.x, z: @payload.y, y: 0, message: (if (== @payload.kind "phase") "ϕ" @payload.glyph), ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.8, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })
      LOG_COLLECT -> idle when (== @entity.active true)
        (set @entity.score @payload.total)
        (set @entity.objectivesLeft (- (array/len @entity.pickups) @payload.total))
        (emit LOG_PROGRESS { objectivesLeft: @entity.objectivesLeft, movesLeft: 9999 })
        (render-ui hud-top {
          type: stack
          direction: horizontal
          justify: center
          className: "p-3"
          children: [ { type: game-hud, variant: "floating", stats: [ { label: "★", value: @entity.score } ] } ]
        })

      LOG_PICKUP_SET_COMPLETED -> idle when (== @entity.active true)
        (emit LOG_BURST { particles: (array/map [ "complete" ] (fn _ { id: "narrative-complete", type: "narrative", x: 0, z: 8, y: 0, message: "domain restricts where the graph lives", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#facc15", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })
        (emit LOG_PROGRESS { objectivesLeft: 0, movesLeft: 9999 })
      LOG_GAME_END -> idle when (and (== @payload.result "won") (== @entity.celebrated false))
        (set @entity.celebrated true)
        (emit RIYA_LEVEL_SOLVED { level: "log" })

      LOG_TUTORIAL_DONE -> idle
        (emit LOG_BURST { particles: (array/map [ "tutorial" ] (fn _ { id: "narrative-tutorial", type: "narrative", x: 0, z: 10, y: 0, message: "log grows fast, then flattens forever", ttl: 3, maxTtl: 3, bornAt: (time/now), space: "world", effect: "float-text", color: "#38bdf8", size: 0.9, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" })) })
    }

    ticks {
      renderTick every 100ms when (== @entity.active true)
        (render-ui main {
          type: game-shell
          appName: (str/concat "riya · " @config.worldName)
          fontFamily: "future-narrow"
          children: [ {
            type: math-canvas
            width: @config.width
            height: @config.height
            xMin: @config.xMin
            xMax: @config.xMax
            yMin: @config.yMin
            yMax: @config.yMax
            showTickLabels: true
            showCurveLabels: true
            keyMap: { ArrowLeft: "LOG_LEFT", KeyA: "LOG_LEFT", ArrowRight: "LOG_RIGHT", KeyD: "LOG_RIGHT", ArrowUp: "LOG_JUMP", KeyW: "LOG_JUMP", Space: "LOG_JUMP" }
            keyUpMap: { ArrowLeft: "LOG_STOP", KeyA: "LOG_STOP", ArrowRight: "LOG_STOP", KeyD: "LOG_STOP" }
            curves: (array/concat
              (array/map @entity.curves (fn c (object/merge @c { color: (if @entity.skating @config.curveSkateColor (object/get @c color)) })))
              @entity.ghostCurves)
            guides: @entity.guides
            bars: (array/map @entity.platforms (fn p { x: (object/get @p x), width: (object/get @p width), y0: (object/get @p y), y1: (+ (object/get @p y) (object/get @p height)), color: @config.terrainColor, opacity: 0.85 }))
            points: (array/concat
              (array/map (array/filter @entity.pickups (fn p (== (object/get @p collected) false))) (fn f { x: (object/get @f x), y: (object/get @f y), label: (object/get @f glyph), color: (if (== (object/get @f kind) "phase") "#22d3ee" @config.starColor), radius: 9 }))
              (array/concat
                [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 0.3), label: "riya", color: @config.riyaColor, radius: 6 } ]
                (array/concat
                  (if @entity.skating [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 1.4), label: (str/concat @config.equationText " · x = " (math/round (+ @entity.body.x 0.3) 1)), color: @config.equationColor, radius: 3 } ] [])
                  (if @config.showTelemetry [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y 2.2), label: (str/concat "x = " (math/round (+ @entity.body.x 0.3) 1) " · y = " (math/round (+ @entity.body.y 0.3) 1) " · v = " (math/round (math/hypot @entity.body.vx @entity.body.vy) 1)), color: @config.equationColor, radius: 3 } ] []))))
            drawables: [ {
              type: "draw-fx-layer"
              items: @entity.fx
              tickMs: 500
              presets: @config.fxPresets
            } ]
            vectors: [ { x: (+ @entity.body.x 0.3), y: (+ @entity.body.y @config.arrowOffsetY), vx: (* @entity.body.vx @config.arrowScale), vy: (* @entity.body.vy @config.arrowScale), color: @config.riyaColor, label: "v" } ]
          } ]
        })
    }

    emits {
      LOG_LEFT -> external {
        id : string
      }
        @description "Run-left intent from ArrowLeft/KeyA keydown or d-pad (forwarded as STEER dir −1)."
        @tier "domain"
      LOG_RIGHT -> external {
        id : string
      }
        @description "Run-right intent from ArrowRight/KeyD keydown or d-pad (forwarded as STEER dir +1)."
        @tier "domain"
      LOG_STOP -> external {
        id : string
      }
        @description "Left/right key release (keyUpMap or d-pad release); forwarded as STEER dir 0."
        @tier "domain"
      LOG_JUMP -> external {
        id : string
      }
        @description "Jump intent from Space/ArrowUp/KeyW or d-pad up; forwarded as the body authority's renamed JUMP (LOG_LEAP), which accepts it only while grounded."
        @tier "domain"
      LOG_STEER -> external {
        dir : number!
      }
        @description "Renamed STEER consumed by this world's platformer-body authority (−1/0/+1 × moveSpeed)."
        @tier "domain"
      LOG_LEAP -> external {
        id : string
      }
        @description "Renamed JUMP consumed by this world's platformer-body authority (grounded-gated vertical kick)."
        @tier "domain"
      LOG_PLACE -> external {
        x : number!
        y : number!
      }
        @description "Renamed PLACE consumed by this world's platformer-body authority; the pit-fall respawn teleport."
        @tier "domain"
      LOG_FELL -> external {
        x : number!
        y : number!
      }
        @description "Pit-fall signal from this world's platformer-body authority (renamed BODY_FELL); respawns riya at her spawn with every star kept."
        @tier "domain"
      LOG_SKATE_ON -> external {
        x : number!
        y : number!
        slope : number!
      }
        @description "Skate-engage signal from this world's platformer-body authority (renamed BODY_SKATE_START); riya touched the log curve — fires the equation fx burst."
        @tier "domain"
      LOG_PICKED -> external {
        id : string!
        kind : string!
        x : number!
        y : number!
        glyph : string
        message : string
      }
        @description "A pickup was collected (renamed PICKED from std-pickup); the play trait bursts the pickup glyph, the challenge trait applies the phase-shift choreography."
        @tier "domain"
      LOG_COLLECT -> external {
        total : number!
      }
        @description "Running pickup count (renamed COLLECT from std-pickup); updates score/objectives and forwards to the objective-flow gate."
        @tier "domain"
      LOG_PICKUP_SET_COMPLETED -> external {
      }
        @description "Every pickup in the set is collected (renamed PICKUP_SET_COMPLETED from std-pickup)."
        @tier "domain"
      LOG_SET_TUNING -> external {
        jumpStrength : number
        moveSpeed : number
        gravity : number
      }
        @description "Renamed SET_TUNING consumed by the platformer-body authority; applies live body tuning overrides."
        @tier "domain"
      LOG_RESTART -> external {
        id : string
      }
        @description "Reseed broadcast consumed by this world's platformer-body/objective-flow authorities (renamed RESTART)."
        @tier "domain"
      LOG_BURST -> external {
        particles : [RiyaLogFx]
      }
        @description "Particle batch spawned on star pickup or pit respawn; fx-particles fades it."
        @tier "domain"
      LOG_PROGRESS -> external {
        objectivesLeft : number!
        movesLeft : number!
      }
        @description "Sparse progress signal emitted by the gameTick only when a star is collected; the objective-flow gate resolves won from it."
        @tier "domain"
      LOG_GAME_END -> external {
        result : string!
      }
        @description "Win-gate resolution from this world's objective-flow authority (renamed GAME_END); won clears the level."
        @tier "domain"
      RIYA_LEVEL_SOLVED -> external {
        level : string
      }
        @description "Every ★ captured — the win gate resolved won (guarded by celebrated so the gate's repeated GAME_ENDs fire it once)."
        @tier "domain"
      LOG_SET_PLATFORMS -> external {
        platforms : [RiyaLogPlatform]!
      }
        @description "Renamed SET_PLATFORMS consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA terrain to collision."
        @tier "domain"
      LOG_SET_SKATE_CURVE -> external {
        curve : [RiyaLogCurveSample]!
      }
        @description "Renamed SET_SKATE_CURVE consumed by this world's platformer-body authority; forwards the canonical RIYA_LEVEL_DATA skate surface."
        @tier "domain"
      LOG_SET_FEATURES -> external {
        features : [RiyaLogPickup]!
      }
        @description "Renamed SET_FEATURES consumed by this world's pickup authority; forwards the canonical RIYA_LEVEL_DATA stars."
        @tier "domain"
    }

    listens {
      LOG_TUTORIAL_DONE { id : string }
      RIYA_LEVEL_DATA {
        id : string!
        name : string!
        equation : string!
        concept : string!
        regionColor : string!
        entryY : number!
        exitY : number!
        platforms : [RiyaLogPlatform]!
        stars : [RiyaLogPickup]!
        skateCurve : [RiyaLogCurveSample]
        curveOverlay : [RiyaLogCurve]
        ghostCurves : [RiyaLogCurve]
        guides : [RiyaLogGuide]
        phaseMods : [RiyaLogPhaseMod]
      }
    }

    config {
      equationText : string = "y = 1.6·ln(x+7) + 1"
        @label "Equation Text"
        @description "Equation of this world's curve, shown by the skate fx burst and the floating label that follows riya while she skates the graph."
        @tier "presentation"
      equationColor : string = "#7dd3fc"
        @label "Equation Color"
        @description "Color of the floating equation label that follows riya while she skates."
        @tier "presentation"
      curveSkateColor : string = "#f0abfc"
        @label "Curve Skate Color"
        @description "Curve trace color while riya is skating the graph (the faint curveOverlay color otherwise)."
        @tier "presentation"
      respawnX : number = -9
        @label "Respawn X"
        @description "X riya teleports to after a pit fall (matches LogBody spawn.x)."
        @tier "domain"
      respawnY : number = 1.2
        @label "Respawn Y"
        @description "Y riya teleports to after a pit fall (matches LogBody spawn.y)."
        @tier "domain"
      reachRadius : number = 0.7
        @label "Reach Radius"
        @description "Manhattan distance from riya's center at which the gameTick counts a star as collected."
        @tier "domain"
      objectiveText : string = "phase unlocks plateau"
        @label "Objective Text"
        @description "Metadata only — not rendered in the HUD. The FX narrative and tutorial carry the objective."
        @tier "presentation"
      worldName : string = "Log"
        @label "World Name"
        @description "This world's display name, shown in the game-shell title chip as \"riya · <worldName>\"."
        @tier "presentation"
      showTelemetry : boolean = false
        @label "Show Telemetry"
        @description "When true, draws a compact x/y/v readout on the canvas near riya (debug aid only). Off by default; teaching text is FX-based."
        @tier "domain"
      conceptText : string = "the logarithm bursts upward then flattens forever; the domain wall x = −7 is forbidden; a phase shift repositions the curve to unlock the far plateau"
        @label "Concept Text"
        @description "The world's one math idea — metadata for the picker/factory, not rendered in-game."
        @tier "presentation"
      riyaColor : string = "#dc2626"
        @label "Riya Color"
        @description "Marker color for riya the dot."
        @tier "presentation"
      starColor : string = "#f59e0b"
        @label "Star Color"
        @description "Marker color for uncollected stars."
        @tier "presentation"
      terrainColor : string = "#78716c"
        @label "Terrain Color"
        @description "Bar color for the ground/platform bars."
        @tier "presentation"
      arrowOffsetY : number = 1.9
        @label "Arrow Offset Y"
        @description "World units above the body center where the velocity vector arrow originates, so it floats above the player sprite."
        @tier "presentation"
      arrowScale : number = 0.5
        @label "Arrow Scale"
        @description "Scale factor for the velocity vector arrow, kept short so it does not dip behind the sprite."
        @tier "presentation"
      fxPresets : [RiyaLogFxPreset] = [ { type: "info", color: "#38bdf8", color2: "#0c4a6e", size: 0.8, shape: "puff", count: 4 }, { type: "pickup", color: "#ffe066", color2: "#ffffff", size: 1.0, shape: "spark", count: 5, glow: 0.12, vy: -0.1 }, { type: "narrative", color: "#38bdf8", size: 1.4, shape: "ring", count: 1, glow: 0.1 } ]
        @label "Fx Presets"
        @description "Look table for world-space particle effects rendered by the draw-fx-layer."
        @tier "presentation"
      xMin : number = -10
        @label "X Min"
        @description "Left edge of the visible math window."
        @tier "presentation"
      xMax : number = 10
        @label "X Max"
        @description "Right edge of the visible math window."
        @tier "presentation"
      yMin : number = -2
        @label "Y Min"
        @description "Bottom edge of the visible math window."
        @tier "presentation"
      yMax : number = 12
        @label "Y Max"
        @description "Top edge of the visible math window."
        @tier "presentation"
      width : number = 800
        @label "Canvas Width"
        @description "math-canvas display width in px."
        @tier "presentation"
      height : number = 480
        @label "Canvas Height"
        @description "math-canvas display height in px."
        @tier "presentation"
    }
  }

  trait LogChallenge -> @rebindable RiyaLogState [game-core, instance] {
    initial: idle

    state idle {
      LOG_PICKED -> idle when (and (== @entity.zoneId @config.zoneId) (== @entity.active true))
        (if (str/endsWith @payload.id "phase")
          (emit LOG_CURVE_MOD_ADD { x0: 0, x1: 9.1, a: 1, h: -2.5, k: 0 })
          null)
        (if (== @payload.kind "phase")
          (emit LOG_BURST { particles: [
            { id: "narrative-phase-fact", type: "narrative", x: @payload.x, z: (+ @payload.y 2), y: 0, message: "f(x+2.5)", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#f472b6", size: 0.7, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" }
            { id: "narrative-phase-hint", type: "narrative", x: @payload.x, z: (+ @payload.y 2.6), y: 0, message: "phase shift unlocks plateau", ttl: 2, maxTtl: 2, bornAt: (time/now), space: "world", effect: "float-text", color: "#a78bfa", size: 0.6, vx: 0, vy: 0, vz: 0, particleCount: 1, animation: "" }
          ] })
          null)
    }

    emits {
      LOG_CURVE_MOD_ADD -> external {
        x0 : number!
        x1 : number!
        a : number!
        h : number!
        k : number!
      }
        @description "Renamed CURVE_MOD_ADD consumed by the platformer-body authority; applies a phase/lift/tilt mod to the skate curve."
        @tier "domain"
      LOG_BURST -> external {
        particles : [RiyaLogFx]
      }
        @description "Particle batch spawned on the phase-pad narrative beat; fx-particles fades it."
        @tier "domain"
    }

    listens {
      LOG_PICKED { id : string!, kind : string!, x : number!, y : number!, glyph : string, message : string }
    }

    config {
      zoneId : string = "log"
        @label "Zone Id"
        @description "The zone this challenge choreography belongs to. Guards compare it against @entity.zoneId, so a composed open world fires it only while riya stands in this zone; standalone the entity default equals this knob and the guard is always true."
        @tier "domain"
    }
  }

  trait RiyaLogClear -> @rebindable RiyaLogState [interaction, instance] {
    initial: watching

    state watching {
      INIT -> watching
        (render-ui overlay null)

      RIYA_LEVEL_SOLVED -> watching
        (render-ui overlay {
          type: game-menu
          title: @config.clearTitle
          subtitle: @config.clearSubtitle
          options: [ { id: "next", label: "Next ▶", event: "LOG_NEXT", variant: "primary" } ]
        })

      LOG_NEXT -> watching
        (render-ui overlay null)
        (navigate @config.nextPath)

      CLOSE -> watching
        (render-ui overlay null)
    }

    listens {
      RIYA_LEVEL_SOLVED { level : string }
      LOG_NEXT { id : string }
      CLOSE
    }

    config {
      nextPath : string = "/riya-log"
        @label "Next Path"
        @description "Page the clear overlay's Next button navigates to. Standalone default replays this world; riya-game-platformer overrides it with the next world's path."
        @tier "presentation"
      clearTitle : string = "Log clear ★"
        @label "Clear Title"
        @description "Overlay title once every star is collected."
        @tier "presentation"
      clearSubtitle : string = "The curve raced up, then flattened — and x = −7 stayed forbidden the whole way."
        @label "Clear Subtitle"
        @description "One-line celebration under the clear title."
        @tier "presentation"
    }
  }

  page "/riya-log" as RiyaLogPage -> LogLevelData, LogBody, LogGate, LogFx, LogPickup, LogTutorial, RiyaLogGenre, RiyaLogPlay, LogChallenge, RiyaLogClear
}
